module ActiveSupport::Dependencies::RequireDependency;def require_dependency(filename)filename=filename.to_path if filename.respond_to?(:to_path);unless filename.is_a?(String);raise ArgumentError,"the file name must be either a String or implement #to_path -- you passed #{filename.inspect}";end;if abspath=ActiveSupport::Dependencies.search_for_file(filename);require abspath;else require filename;end;end;Object.prepend(self);end
